import{_ as s,c as a,o as e,a2 as n}from"./chunks/framework.PGES7OoM.js";const k=JSON.parse('{"title":"reconcileOperation","description":"Recheck chain evidence before releasing intermediate outputs from an interrupted operation.","frontmatter":{"editLink":false,"rawMarkdown":"# reconcileOperation\\n\\nRecheck chain evidence before releasing intermediate outputs from an interrupted operation.\\n\\n## Import\\n\\n```ts\\nimport { reconcileOperation } from \\"@0xcurvy/curvy-sdk/actions\\";\\n```\\n\\n## Usage\\n\\n```ts\\nconst result = await reconcileOperation({ operationId, config });\\n```\\n\\n## Signature\\n\\n```ts\\nfunction reconcileOperation(parameters: ReconcileOperationParameters): Promise<ReconcileOperationResult>\\n```\\n\\n## Returns\\n\\n`Promise<ReconcileOperationResult>`\\n\\nThe action resolves or returns the value shown in the signature.\\n\\n## Parameters\\n\\n### `operationId`\\n\\n- **Type:** `string`\\n- **Required:** yes\\n\\nThe interrupted operation whose chain evidence is rechecked.\\n\\n```ts\\nconst result = await reconcileOperation({\\n  operationId, // [!code focus]\\n});\\n```\\n\\n### `accountId`\\n\\n- **Type:** `string`\\n- **Required:** no\\n\\nThe account that owns the operation. Defaults to the active account.\\n\\n```ts\\nconst result = await reconcileOperation({\\n  operationId,\\n  accountId, // [!code focus]\\n});\\n```\\n\\n### `signal`\\n\\n- **Type:** `AbortSignal`\\n- **Required:** no\\n\\nAborts the chain reads.\\n\\n```ts\\nconst result = await reconcileOperation({\\n  operationId,\\n  signal, // [!code focus]\\n});\\n```\\n\\n### `config`\\n\\n- **Type:** `CurvyConfig`\\n- **Required:** no\\n\\nCurvy config to use. Defaults to the ambient config.\\n\\n```ts\\nconst result = await reconcileOperation({\\n  operationId,\\n  config, // [!code focus]\\n});\\n```\\n\\n## Errors\\n\\nErrors from config resolution and the underlying SDK operation are propagated to the caller.\\n\\n## Related\\n\\n- [Interacting with assets guide](/for-programmers/interacting-with-assets)\\n\\n## Source\\n\\n[packages/@0xcurvy/sdk/src/actions/views/reconcileOperation.ts](https://github.com/0xCurvy/curvy-monorepo/blob/main/packages/@0xcurvy/sdk/src/actions/views/reconcileOperation.ts)\\n","rawMarkdownPath":"/_raw/sdk/actions/views/reconcileOperation.md","rawMarkdownTitle":"reconcileOperation","rawMarkdownUrl":"https://docs.curvy.box/_raw/sdk/actions/views/reconcileOperation.md"},"headers":[],"params":{"sdkReferenceKind":"action","category":"views","action":"reconcileOperation"},"relativePath":"sdk/actions/views/reconcileOperation.md","filePath":"sdk/actions/[category]/[action].md","lastUpdated":1786448401000}'),t={name:"sdk/actions/views/reconcileOperation.md"};function r(o,i,l,h,p,c){return e(),a("div",null,[...i[0]||(i[0]=[n("",34)])])}const u=s(t,[["render",r]]);export{k as __pageData,u as default};
